"use client";

import Link from "next/link";
import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  ArrowDownWideNarrow,
  ArrowRight,
  BookOpen,
  Bookmark,
  Check,
  CheckCheck,
  Leaf,
  LoaderCircle,
  Plus,
  Search,
  Sparkles,
  StickyNote,
  X,
} from "lucide-react";
import type { Book, BookStatus } from "@/lib/types";
import { setStatusAction } from "@/app/actions";
import { Brand, Footer } from "./brand";
import { AddBookDialog } from "./add-book-dialog";
import { BookCover } from "./book-cover";

type Filter = "all" | BookStatus;

function ReadingCard({ book }: { book: Book }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState("");
  return (
    <article className="reading-card">
      <Link
        href={`/books/${book.id}`}
        className={`cover-stage stage-${book.color}`}
        aria-label={`Open ${book.title}`}
      >
        <span className="reading-badge">
          <span /> Reading
        </span>
        <BookCover book={book} />
        <span className="cover-open">
          <ArrowRight size={18} />
        </span>
      </Link>
      <div className="card-content">
        <Link className="book-title-link" href={`/books/${book.id}`}>
          <h3>{book.title}</h3>
        </Link>
        <p className="book-author">{book.author}</p>
        <div className="card-footer">
          <Link href={`/books/${book.id}#notes`} className="notes-link">
            <StickyNote size={14} />
            {book.notes ? "View notes" : "Add a note"}
          </Link>
          <button
            className="finish-button"
            disabled={pending}
            aria-label={`Mark ${book.title} as finished`}
            onClick={() => {
              setError("");
              startTransition(async () => {
                const result = await setStatusAction(book.id, "finished");
                if (result.error) setError(result.error);
                else router.refresh();
              });
            }}
          >
            {pending ? (
              <LoaderCircle size={14} className="spin" />
            ) : (
              <Check size={14} />
            )}
            <span>{pending ? "Saving…" : "Mark finished"}</span>
          </button>
        </div>
        {error && (
          <p className="error-message" role="alert">
            {error}
          </p>
        )}
      </div>
    </article>
  );
}

function FinishedCard({ book }: { book: Book }) {
  return (
    <Link className="finished-card" href={`/books/${book.id}`}>
      <div className={`finished-cover-stage stage-${book.color}`}>
        <BookCover book={book} small />
      </div>
      <div className="finished-content">
        <span className="finished-badge">
          <CheckCheck size={13} /> FINISHED
        </span>
        <h3>{book.title}</h3>
        <p className="book-author">{book.author}</p>
        <span className="finished-date">
          {book.finishedAt
            ? `Closed the last page ${new Date(book.finishedAt).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" })}`
            : "Another story to carry with you"}
        </span>
      </div>
      <ArrowRight size={18} className="finished-arrow" />
    </Link>
  );
}

export function Library({ books }: { books: Book[] }) {
  const [adding, setAdding] = useState(false);
  const [filter, setFilter] = useState<Filter>("all");
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState("recent");
  const readingCount = books.filter((book) => book.status === "reading").length;
  const finishedCount = books.length - readingCount;
  const visible = useMemo(
    () =>
      books
        .filter((book) =>
          `${book.title} ${book.author}`
            .toLowerCase()
            .includes(query.toLowerCase().trim()),
        )
        .sort((a, b) =>
          sort === "title"
            ? a.title.localeCompare(b.title)
            : b.createdAt.localeCompare(a.createdAt),
        ),
    [books, query, sort],
  );
  const reading = visible.filter((book) => book.status === "reading");
  const finished = visible.filter((book) => book.status === "finished");
  const noMatches =
    (filter === "all" ? visible : filter === "reading" ? reading : finished)
      .length === 0;

  return (
    <div className="site-shell">
      <header className="header">
        <Brand />
        <nav aria-label="Main navigation">
