/bin/bash -lc "node --input-type=module <<'JS'
import { chromium } from '@playwright/test';
const browser = await chromium.launch({headless: true});
const page = await browser.newPage({ viewport: { width: 1440, height: 1100 } });
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://localhost:3000');
await page.waitForLoadState('networkidle');
await page.screenshot({ path: '/tmp/folio-desktop.png', fullPage: true });
console.log(JSON.stringify({title: await page.title(), images: await page.locator('img').evaluateAll(images=>images.map(i=>({src:i.getAttribute('src'),loaded:i.complete&&i.naturalWidth>0}))), errors}));
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/folio-mobile.png',fullPage:true});
await browser.close();
JS"

